-- Grant Radar seed: real Indian non-dilutive programs accessible to student founders.
-- 15 rows, researched and sourced; re-runnable (upsert on name).

on conflict (name) do update set agency = excluded.agency, program_type = excluded.program_type, amount_max_inr = excluded.amount_max_inr, amount_display = excluded.amount_display, domains = excluded.domains, eligibility_summary = excluded.eligibility_summary, student_friendly = excluded.student_friendly, needs_registered_company = excluded.needs_registered_company, how_to_apply = excluded.how_to_apply, url = excluded.url, typical_timeline = excluded.typical_timeline, source_url = excluded.source_url, as_of_date = excluded.as_of_date;
