insert into public.grants (name, agency, program_type, amount_max_inr, amount_display, domains, eligibility_summary, student_friendly, needs_registered_company, how_to_apply, url, typical_timeline, source_url, as_of_date) values
  ('NIDHI-PRAYAS', 'DST (NSTEDB/NIDHI), Govt of India', 'grant', 1000000, 'up to ₹10 lakh prototype grant', '{"hardware","deeptech"}', 'Open to individual Indian innovators aged 18+ with a technology idea that can reach a working prototype within 18 months; no registered company is required. Students and researchers can apply with a No Objection Certificate (NOC) from their institution granting them time to work on the PRAYAS project. Selection is done by DST-approved PRAYAS Centres (PCs) and Advanced PRAYAS Centres (APCs) hosted at incubators.', true, false, 'Apply to an approved PRAYAS Centre / Advanced PRAYAS Centre (hosted at NIDHI incubators such as CCAMP and many TBIs) when it opens a call; the PC screens, funds and mentors the prototype.', 'https://nidhi-prayas.org/', 'Rolling/periodic calls via PRAYAS Kendras at incubators across India; prototype must be completed within 18 months of award', 'https://nidhi-prayas.org/innovators/', '2026-08'),
  ('NIDHI-EIR (Entrepreneur-in-Residence)', 'DST (NIDHI), Govt of India', 'grant', 360000, '₹30,000/month fellowship, total capped at ₹3.6 lakh (up to 18 months)', '{"all"}', 'Subsistence fellowship for aspiring entrepreneurs pursuing a technology business idea full-time. Applicants must be Indian citizens, must NOT be enrolled as full-time students (it targets fresh graduates and those ready to commit full-time), must not hold more than 10% equity in any company, and cannot draw another fellowship or salary. It is explicitly pre-incorporation: no registered company is needed, and having one largely disqualifies you.', true, false, 'Apply through a NIDHI-EIR partner Technology Business Incubator (TBI) when it announces an EIR cohort call; the TBI selects and hosts the EIRs.', 'https://nidhi.dst.gov.in/nidhieir/', 'Cohort calls announced by partner TBIs through the year; support runs 12-18 months', 'https://www.indiascienceandtechnology.gov.in/listingpage/nidhi-entrepreneur-residence-eir', '2026-08'),
  ('Startup India Seed Fund Scheme (SISFS)', 'DPIIT, Govt of India', 'grant', 5000000, 'up to ₹20 lakh grant (PoC/validation) + up to ₹50 lakh via convertible debentures/debt (market entry & scaling)', '{"all"}', 'For DPIIT-recognised startups (Pvt Ltd, LLP or registered partnership) incorporated not more than 2 years before application, with a technology-based innovative business and at least 51% Indian promoter shareholding. Startups that have already received more than ₹10 lakh monetary support under other central/state schemes are ineligible; sole proprietorships and unregistered student teams cannot apply.', false, true, 'Apply online at seedfund.startupindia.gov.in, selecting up to 3 approved incubators; the incubator''s ISMC screens applications and disburses milestone-based funds.', 'https://seedfund.startupindia.gov.in/', 'Application portal is always open; incubator selection committees evaluate on a rolling (roughly monthly/quarterly) basis', 'https://www.indiascienceandtechnology.gov.in/funding-opportunities/startups/startup-india-seed-fund-scheme-sisfs', '2026-08'),
  ('Karnataka ELEVATE (Idea2PoC Grant-in-Aid)', 'Startup Karnataka / KITS, Govt of Karnataka', 'grant', 5000000, 'one-time grant-in-aid up to ₹50 lakh', '{"all"}', 'For startups registered in Karnataka as a private limited company, LLP or partnership firm (turnover under ₹100 crore); DPIIT recognition is NOT mandatory. The unified 2026 (25th) call runs 4 parallel tracks: ELEVATE General, ELEVATE Shakti (at least 51% women-owned), ELEVATE Unnati (SC/ST founders) and ELEVATE Aspire (startups beyond Bengaluru, formerly ''Beyond Bengaluru''); a deeptech variant, ELEVATE NXT, has offered up to ₹1 crore. A registered Karnataka entity is required, so student teams must incorporate first. Formally this is the Idea2PoC grant-in-aid scheme — Idea2PoC no longer exists as a separate program.', false, true, 'Apply online at elevate.startupkarnataka.in during an open call, choosing the applicable track; shortlisted startups pitch to expert panels and winners get milestone-based grant-in-aid plus incubation/mentorship.', 'https://elevate.startupkarnataka.in/', 'Roughly annual calls; the 25th call opened April/May 2026 with deadline extended to 15 Jul 2026', 'https://yourstory.com/2026/04/karnataka-elevate-25th-call-startup-grant-2026', '2026-08'),
  ('MeitY TIDE 2.0', 'MeitY (MeitY Startup Hub), Govt of India', 'grant', 700000, 'EiR support up to ₹4 lakh (idea/PoC stage) + grant up to ₹7 lakh (prototype stage)', '{"ai_ml","saas","hardware","deeptech","fintech","healthtech","edtech"}', 'Runs through 51 TIDE 2.0 incubation centres at institutes of higher learning (IITs, IIITs, NITs, IISc-FSID, etc.) for tech ventures using emerging tech (IoT, AI, blockchain, robotics) in sectors like healthcare, education, agriculture, fintech and cleantech. The EiR track supports individuals at idea/PoC stage with up to ₹4 lakh plus a year of pre-incubation — no registered company needed — while the ₹7 lakh prototype-stage grant goes to incorporated startups. Over 1,700 startups supported as of 2025 (scheme still active per PIB, March 2025).', true, false, 'Apply directly to a TIDE 2.0 centre (list on the MeitY Startup Hub portal) when it opens an EiR or grant cohort; each centre screens and onboards its own cohorts.', 'https://msh.meity.gov.in/schemes/tide', 'Rolling cohort intakes announced individually by the 51 TIDE 2.0 centres', 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2206765', '2026-08'),
  ('BIRAC Biotechnology Ignition Grant (BIG)', 'BIRAC, Dept of Biotechnology, Govt of India', 'grant', 5000000, '₹50 lakh grant-in-aid over 18 months', '{"healthtech","deeptech","climate"}', 'For biotech/life-sciences innovations moving from idea to proof of concept. Open to individual Indian-citizen innovators — including research scholars and PG students pursuing translational research, with an NOC from their institute — provided they are (or agree to be) physically incubated at a BIG Partner incubator; alternatively a registered company with a functional R&D lab can apply. No registered company is required if you take the incubatee route.', true, false, 'Apply online on the BIRAC portal during an open call, routed through one of the BIG Partner incubators that hosts and mentors awardees.', 'https://birac.nic.in/big.php', 'Calls twice a year, announced 1 January and 1 July, open ~45 days (25th call ran in 2025 with deadline extended to 30 Nov 2025)', 'https://birac.nic.in/big.php', '2026-08'),
  ('iDEX (DISC & Open Challenges)', 'Defence Innovation Organisation (DIO), Ministry of Defence', 'grant', 15000000, 'SPARK grant up to ₹1.5 crore (milestone-based, with matching contribution)', '{"defence","spacetech","deeptech","hardware","ai_ml"}', 'Startups, MSMEs, R&D institutions AND individual innovators can apply against posted defence/aerospace problem statements; DPIIT recognition is not mandatory. Grants of up to ₹1.5 crore are non-dilutive, disbursed milestone-wise under the SPARK framework, and generally expect a matching contribution from the winner. Individual innovators/student teams with a relevant proof of concept can enter DISC rounds and iDEX Open Challenges without a registered company.', true, false, 'Register on idex.gov.in and submit against a live Defence India Startup Challenge (DISC) or iDEX Open Challenge problem statement; winners sign milestone-based SPARK grant agreements with DIO.', 'https://idex.gov.in/', 'Challenge-driven: numbered DISC rounds (DISC 14 live in 2026) plus rolling Open Challenges', 'https://idex.gov.in/faq', '2026-08'),
  ('IN-SPACe Seed Fund Scheme', 'IN-SPACe, Dept of Space, Govt of India', 'grant', 10000000, 'up to ₹1 crore grant, milestone-based in 3+ instalments', '{"spacetech"}', 'For DPIIT-registered startups and micro/small enterprises building upstream, midstream or downstream space-technology solutions; recent thematic calls covered urban development, disaster management, agriculture and mission virtualisation. The grant (up to ₹1 crore) is released milestone-wise and must be fully utilised within 3 years, with ISRO facility/EO-data access and mentorship included. A registered entity is required, so student teams must incorporate first.', false, true, 'Apply through the IN-SPACe digital platform (inspace.gov.in) when a Seed Fund call is announced; an expert committee selects and sets instalment milestones.', 'https://www.inspace.gov.in/inspace?id=kb_article&sysparm_article=KB0010016', 'Thematic calls announced periodically on inspace.gov.in; project execution up to 3 years', 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2115883', '2026-08'),
  ('MSME Innovative Scheme – Incubation (via Host Institutes)', 'Ministry of MSME, Govt of India', 'grant', 1500000, 'up to ₹15 lakh per approved idea (routed through the Host Institute)', '{"all"}', 'Individuals and students with an innovative idea apply through a registered MSME Host Institute (HI), which incubates the idea and receives up to ₹15 lakh per approved idea as milestone-based grant-in-aid — no registered company is needed. RV College of Engineering (RVCE), Bengaluru is a recognised MSME Host Institute (MSME has sanctioned ~₹34.85 lakh for three RVCE ideas), so RVCE students can route applications directly through campus. HIs can also get up to ₹1 crore for plant & machinery to support incubatees.', true, false, 'Submit your idea to a registered Host Institute (e.g. RVCE''s incubation cell); the HI recommends and uploads it on the MSME Innovative portal (innovative.msme.gov.in) for approval and funding.', 'https://my.msme.gov.in/inc/AboutIncubation.aspx', 'Rolling: ideas accepted by Host Institutes year-round, subject to the HI''s annual idea quota and fund availability', 'https://innovative.msme.gov.in/Documents/MSME_InnovativeFAQ.pdf', '2026-08'),
  ('Hult Prize', 'Hult Prize Foundation (global, backed by EF/Hult family)', 'competition', 85000000, 'US$1 million global grand prize (~₹8.5 crore); campus and national rounds feed into it', '{"all"}', 'The world''s largest student startup competition, run across 2,000+ campuses in 121 countries: teams of currently enrolled university students compete via their campus qualifier (OnCampus) or the open online application — no registered company is required to enter. Ventures must align with at least one UN Sustainable Development Goal and show a people/planet/profit triple-bottom-line. The 2026 season drew ~18,000 registered startups, with global finals at Ashridge House in September 2026.', true, false, 'Join or organise your college''s Hult Prize OnCampus qualifier (student campus director route), or apply directly online at hultprize.org; winners advance to nationals, the global accelerator and the $1M final.', 'https://www.hultprize.org/', 'Annual cycle: campus qualifiers roughly Sep-Dec, national rounds ~Apr-Jun, global finals in September', 'https://www.prnewswire.com/news-releases/hult-prize-nationals-underway-across-45-global-competitions-as-2-000-startups-vie-for-1-million-prize-302791617.html', '2026-08'),
  ('Karnataka NAIN 2.0 (New Age Innovation Network) — K-tech', 'KITS, Dept of Electronics, IT, BT & S&T, Govt of Karnataka', 'grant', 500000, '₹5 lakh government grant per selected student project (was ₹3 lakh under NAIN 1.0)', '{"all"}', 'K-tech/KITS program that funds student innovation projects at selected NAIN 2.0 host colleges across Karnataka: each selected student project receives a ₹5 lakh grant to build a working prototype solving local problems using frugal innovation. Students apply through their own college''s NAIN centre — no company registration is needed — but it is only accessible if your institution is one of the selected NAIN host colleges (largely beyond-Bengaluru institutions; IIIT Dharwad is the Project Monitoring Unit).', true, false, 'Apply via your college''s NAIN 2.0 centre if it is a selected host institution; the college screens student projects and KITS approves funding, with a ~6-month project execution cycle.', 'https://startup.karnataka.gov.in/new-age-innovation-network/', 'Host institutions selected in cohorts by KITS; student projects run in ~6-month cycles (NAIN 2.0 selections active in 2026)', 'https://www.mitkundapura.com/index.php/2026/06/16/mitk-selected-for-nain-2-0/', '2026-08'),
  ('NIDHI Seed Support Scheme (NIDHI-SSS/SSP)', 'DST (NSTEDB/NIDHI), Govt of India', 'convertible', 10000000, 'typically ₹20-50 lakh, exceptionally up to ₹1 crore (via CCDs/equity-linked instruments)', '{"all"}', 'For registered Indian startups (≥51% Indian promoter shareholding) that have been physically incubated for at least ~3 months at a participating DST-supported TBI, with an MVP, customer validation and a formal business plan. Funding flows through the incubator as compulsorily convertible debentures or other equity-linked instruments — quasi-equity, not a pure grant. Not open to individuals or unregistered student teams, nor to Indian subsidiaries of MNCs.', false, true, 'Apply to a NIDHI-SSS participating Technology Business Incubator (e.g. IIT/IISc-linked TBIs) during its periodic seed-support calls; the TBI''s committee evaluates and structures the investment.', 'https://nidhi.dst.gov.in/nidhissp/', 'Rolling via participating TBIs; requires ~3 months of incubation before seed support', 'https://www.nstedb.com/NIDHI-Seed-Support-Program-Guidelines.pdf', '2026-08'),
  ('Atal New India Challenge (ANIC 2.0)', 'Atal Innovation Mission, NITI Aayog', 'grant', 10000000, 'up to ₹1 crore grant, milestone-based over 12-18 months', '{"all"}', 'Challenge-based productisation grant for technologies addressing sectoral problems of national importance (education, health, water & sanitation, agriculture, housing, energy, mobility, space applications, etc.). Open to startups and MSMEs registered in India responding to posted challenge statements — a registered company is required, and exact award size is decided by AIM committees per application. Support is strictly round-based: apply only when a challenge round is live on aim.gov.in.', false, true, 'Apply online on aim.gov.in against a live ANIC challenge statement; selected applicants receive milestone-based grants plus AIM incubation support.', 'https://aim.gov.in/atal-new-india-challenge-2.0.php', 'Round-based: challenge tranches announced periodically by AIM (ANIC 2.0 launched 2022; check aim.gov.in for live rounds)', 'https://aim.gov.in/anic-application-guidelines.php', '2026-08'),
  ('Villgro (iPitch & sector programs)', 'Villgro Innovations Foundation (non-profit incubator)', 'incubation', 2500000, 'seed support up to ~₹25 lakh (mix of grant, debt & technical assistance; varies by program)', '{"climate","healthtech"}', 'India''s oldest social-enterprise incubator, backing early-stage impact startups in agriculture, climate action, healthcare, livelihoods and shelter-tech with seed funding of up to ~₹25 lakh deployed as a mix of grant, debt, equity and technical assistance depending on the program (e.g. the SBI Foundation ''Innovators for Bharat'' climate-agri program deploys ₹3.25 crore across its cohort). Its annual iPitch call is a national deal-discovery window into Villgro and partner-investor funding. Applicants are registered social enterprises — student teams without an entity are generally not fundable.', false, true, 'Apply to the annual iPitch call or a live sector program on villgro.org; selected ventures get funding plus incubation and technical assistance.', 'https://villgro.org/programs/ipitch/', 'Annual iPitch call plus multiple sector-specific cohort programs announced through the year', 'https://villgro.org/programs/', '2026-08'),
  ('Social Alpha (Techtonic accelerators)', 'Social Alpha / FISE (Tata Trusts-supported non-profit)', 'incubation', 6000000, 'program grants ~₹10 lakh (early R&D) to ₹60 lakh (growth stage); follow-on seed up to ₹1 crore for portfolio startups', '{"climate","deeptech","healthtech"}', 'Venture development platform for science- and deeptech-led startups with social/climate impact, running lab-to-market accelerators such as Techtonic (clean energy, circular economy). Its clean-energy accelerator offers incubation support of ₹10 lakh for early R&D-stage companies and up to ₹60 lakh for growth-stage ones, with earlier Techtonic editions granting ₹15 lakh plus a year of incubation to top startups and Social Alpha seed funding of up to ₹1 crore for portfolio companies. A registered entity is expected for funding, though early innovators can engage for incubation.', false, true, 'Apply to a live Techtonic/accelerator cohort call on socialalpha.org; selected startups receive grants, incubation, pilots and potential Social Alpha seed investment.', 'https://www.socialalpha.org/techtonic/', 'Cohort calls per program (clean energy, circular economy, health etc.) announced on socialalpha.org through the year', 'https://www.eqmagpro.com/social-alpha-launches-clean-energy-accelerator-offering-grants-of-up-to-%E2%82%B960-lakh-for-startups-eq/', '2026-08')
